from ortools.sat.python import cp_model
import json

# Input data
jobs_data = [  # (job_id, task_id) -> (machine_id, duration)
    [(0, 3), (1, 2), (2, 2)],  # Job 0
    [(0, 2), (2, 1), (1, 4)],  # Job 1
    [(1, 4), (2, 3)]           # Job 2
]

# Model definition
model = cp_model.CpModel()

# Number of jobs and machines
num_jobs = len(jobs_data)
num_machines = 1 + max(task[0] for job in jobs_data for task in job)

# Decision Variables
# start[job][task] is the start time of the task for the job.
start = {}
end = {}
duration = {}
for job_id, job in enumerate(jobs_data):
    for task_id, task in enumerate(job):
        machine_id, duration_value = task
        start[(job_id, task_id)] = model.NewIntVar(0, 1000, f'start[{job_id},{task_id}]')
        end[(job_id, task_id)] = model.NewIntVar(0, 1000, f'end[{job_id},{task_id}]')
        duration[(job_id, task_id)] = duration_value

# Constraints
# Each task starts after the previous task of the same job ends.
for job_id, job in enumerate(jobs_data):
    for task_id in range(1, len(job)):
        model.Add(start[(job_id, task_id)] >= end[(job_id, task_id - 1)])

# Each machine can only work on one task at a time.
for machine_id in range(num_machines):
    intervals = []
    for job_id, job in enumerate(jobs_data):
        for task_id, task in enumerate(job):
            if task[0] == machine_id:
                intervals.append(
                    model.NewIntervalVar(start[(job_id, task_id)], duration[(job_id, task_id)], end[(job_id, task_id)],
                                         f'interval[{job_id},{task_id}]'))
    model.AddNoOverlap(intervals)

# Objective function: minimize the makespan
makespan = model.NewIntVar(0, 1000, 'makespan')
for job_id, job in enumerate(jobs_data):
    model.Add(makespan >= end[(job_id, len(job) - 1)])
model.Minimize(makespan)

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        'makespan': solver.Value(makespan)
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
