words_sorted = sorted(words, key=lambda x: (-len(x), x))
word_indices = {word: idx for idx, word in enumerate(words_sorted)}

# Crossword grid size
rows = 6
cols = 5

# Word lengths
word_lengths = {word: len(word) for word in words_sorted}

# Starting positions
start_positions = {
    1: (0, 0), 2: (0, 2), 3: (0, 4),
    4: (2, 1), 5: (2, 3),
    6: (3, 0), 7: (3, 2),
    8: (4, 0)
}

# Model definition
model = cp_model.CpModel()

# Decision Variables
# E[i] is the index of the word starting at position i
E = [model.NewIntVar(0, len(words_sorted) - 1, f'E_{i}') for i in start_positions]

# Constraints
# Each starting position must have a unique word
model.AddAllDifferent(E)

# Function to check if a word fits in a given direction
def fits(word, grid, start_row, start_col, direction):
    if direction == 'horizontal':
        if start_col + len(word) > cols:
            return False
        for i, char in enumerate(word):
            if grid[start_row][start_col + i] != '' and grid[start_row][start_col + i] != char:
                return False
    elif direction == 'vertical':
        if start_row + len(word) > rows:
            return False
        for i, char in enumerate(word):
            if grid[start_row + i][start_col] != '' and grid[start_row + i][start_col] != char:
                return False
    return True

# Function to place a word in the grid
def place_word(word, grid, start_row, start_col, direction):
    if direction == 'horizontal':
        for i, char in enumerate(word):
            grid[start_row][start_col + i] = char
    elif direction == 'vertical':
        for i, char in enumerate(word):
            grid[start_row + i][start_col] = char

# Initial empty grid
grid = [['' for _ in range(cols)] for _ in range(rows)]

# Add constraints for each starting position
for i, (start_row, start_col) in start_positions.items():
    for word_idx in range(len(words_sorted)):
        word = words_sorted[word_idx]
        # Check if the word fits horizontally
        if fits(word, grid, start_row, start_col, 'horizontal'):
            # Create a boolean variable to indicate if this word is placed here
            is_placed_horizontal = model.NewBoolVar(f'is_placed_horizontal_{i}_{word_idx}')
            # If the word is placed here, set the grid cells
            for j in range(word_lengths[word]):
                model.Add(grid[start_row][start_col + j] == word[j]).OnlyEnforceIf(is_placed_horizontal)
            # Ensure that if the word is placed here, the corresponding E[i] is set to word_idx
            model.Add(E[i] == word_idx).OnlyEnforceIf(is_placed_horizontal)
        # Check if the word fits vertically
        if fits(word, grid, start_row, start_col, 'vertical'):
            # Create a boolean variable to indicate if this word is placed here
            is_placed_vertical = model.NewBoolVar(f'is_placed_vertical_{i}_{word_idx}')
            # If the word is placed here, set the grid cells
            for j in range(word_lengths[word]):
                model.Add(grid[start_row + j][start_col] == word[j]).OnlyEnforceIf(is_placed_vertical)
            # Ensure that if the word is placed here, the corresponding E[i] is set to word_idx
            model.Add(E[i] == word_idx).OnlyEnforceIf(is_placed_vertical)
        # Ensure that the word is placed either horizontally or vertically
        model.AddBoolOr([is_placed_horizontal, is_placed_vertical])

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)

if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {'E': [solver.Value(e) for e in E]}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
